/** Numbered history stays in src as engine stays, placed through the candidate's canonical plan command [C7,D3,H16]. */
import { spawnSync } from 'node:child_process';
import { existsSync } from 'node:fs';
import { join } from 'node:path';
import { cleanGitEnvironment } from '../../../../src/git.js';
import { git } from '../../../../src/git.js';
import { Refused } from '../../../kernel/index.js';

/** Place only histories generated by this allocation; unrelated projects without a cells plan stay untouched. */
export function placeLandingHistory(root, files, { place = placeWithPlan } = {}) {
  const histories = files.filter(file => /^src\/move-history\/\d+\.json$/u.test(file));
  if (!histories.length || !existsSync(join(root, 'bin/cells-plan.json'))) return [];
  for (const file of histories) {
    // The placer refuses an untracked file ("stage a regular source file before placing it"), and a generated history
    // is new in the landing worktree. Why: on 6 Nov every merge that allocated an engine failed here for seven hours,
    // LAND_MERGE then a dirty worktree, and the lander adopted the same pair every minute [C7,D3].
    if (existsSync(join(root, file))) git(root, ['add', '--', file]);
    const result = place(root, file);
    if (result.status !== 0) {
      const detail = String(result.stderr ?? '').split('\n').find(line => /\[[A-Z_]+\]/u.test(line)) ?? '';
      throw new Refused('LAND_MERGE', `canonical state rule placement failed for ${file}${detail ? `: ${detail.trim()}` : ''}; repair the cells plan and retry landing`);
    }
  }
  return git(root, ['diff', '--name-only', 'HEAD', '--', 'bin/cells-plan.json', 'bin/cells-plan/']).split('\n').filter(Boolean);
}

/** The canonical placement command, run in the landing worktree with a clean Git environment. */
function placeWithPlan(root, file) {
  return spawnSync(process.execPath, ['bin/cells-plan.js', '--place', file, '--stay'], {
    cwd: root, env: cleanGitEnvironment(), encoding: 'utf8', timeout: 30_000, maxBuffer: 32 * 1024 * 1024,
  });
}
